29 L34.68 64.26 L34.13 64.23 L33.57 64.20 L33.01 64.17 L32.43 64.15 L31.85 64.13 L31.26 64.11 L30.66 64.11 L30.06 64.11 L29.45 64.12 L28.84 64.14 L28.23 64.17 L27.61 64.22 L26.99 64.28 L26.36 64.35 L25.74 64.44 L25.11 64.55 L24.48 64.67 L23.85 64.82 L23.22 64.98 L22.60 65.17 L21.97 65.38 L21.35 65.61 L20.73 65.87 L20.11 66.15 L19.50 66.47 L18.89 66.80 Z" fill="#000"></path></mask></defs><rect width="100" height="100" rx="12" fill="currentColor" mask="url(#bp-mark-mask)"></rect></svg>Blackpool<span class="cl-brand-sub">Recover</span></a><nav class="cl-nav-links"><a href="/">Home</a><a href="/docs">Docs</a><a href="/agents">Agents</a><a href="/analytics">Analytics</a><a href="/changelog">Changelog</a></nav><a class="cl-btn" href="/app">Launch app</a></div></header><div class="cl-wrap"><div class="cl-head"><h1>Recover</h1><p class="rc-lead">Anything that can get stuck is recoverable from your signature alone. Open this page in the wallet you used, sign once, and every burner registered to that wallet is found, swept back and listed with your bridges.</p></div><section class="rc-tool"><div class="cl-vis rc-vis"><div class="cl-mock wide rc-win"><div class="cl-mock-h">Recover funds<span>Scans Robinhood Chain · Base · Arbitrum · BNB Chain for one-time swap wallets</span></div><div class="cl-chips"><span class="cl-chip"><i class="rc-dot" style="background:#34C77B"></i>Robinhood Chain</span><span class="cl-chip"><i class="rc-dot" style="background:#4C7FE3"></i>Base</span><span class="cl-chip"><i class="rc-dot" style="background:#7B68E0"></i>Arbitrum</span><span class="cl-chip"><i class="rc-dot" style="background:#E9A23B"></i>BNB Chain</span></div><div class="cl-kv"><span>Wallet</span><b class="">not connected</b></div><div class="cl-kv"><span>Signature</span><b>1 · stays in this browser</b></div><div class="cl-kv"><span>Burner registry</span><b>decrypted locally</b></div><button class="cl-btn rc-btn">Recover my funds</button><div class="rc-console"><div class="rc-console-h"><span class="mono">log</span><span class="cl-pill ">idle</span></div><pre class="rc-log"><span class="rc-prompt">&gt; waiting for signature</span>
  press Recover my funds to start. Output stays on this device.</pre></div><div class="cl-mock-f">No seed phrases, no exports. Funds return to the wallet you sign with.</div></div></div></section><section class="rc-tiles"><div class="rc-tile"><h3>Your signature stays local</h3><p>Recover decrypts your burner registry in the browser and signs sweeps there. Nothing secret is sent to a server.</p></div><div class="rc-tile"><h3>Burners from any device</h3><p>Every one-time swap wallet is registered encrypted at creation, so a swap that stalls is recoverable anywhere.</p></div><div class="rc-tile"><h3>Bridges and refunds</h3><p>Every cross-chain intent is listed with its status. A failed bridge shows where the refund went.</p></div></section><section class="cl-cta"><h2>Move value privately.<br><span>Start with one signature.</span></h2><p>Connect a wallet, sign once, and your private account exists on every supported chain.</p><a class="cl-btn lg" href="/app">Launch app</a></section><p class="cl-foot">© 2026 Blackpool. Recovery uses public RPC endpoints; keys never leave your device.</p></div></main>
<ConnectModal
  v-if="connectOpen"
  :wallets="wallets"
  :connecting-id="connectingId"
  :error="walletError"
  @close="connectOpen = false"
  @select="selectWallet"
  @browser="selectBrowser"
/>
</template>

<style src="../../styles/content/content.css"></style>
<style src="../../styles/content/recover.css"></style>
<style src="../../styles/app.css"></style>

<script setup>
import { onBeforeUnmount, onMounted, ref, watch } from 'vue'
import ConnectModal from '../../components/app/ConnectModal.vue'
import { usePrivateAccount } from '../../composables/usePrivateAccount'
import { useWallet } from '../../composables/useWallet'
import { shortAddress, wait } from '../../utils/format'

const wallet = useWallet()
wallet.init()

const { address, connected, connectingId, error: walletError, wallets } = wallet
const account = usePrivateAccount()

const connectOpen = ref(false)
let scanning = false
let button = null

function logLine(text) {
  const log = document.querySelector('.rc-log')
  if (!log) return
  const span = document.createElement('span')
  span.className = 'rc-prompt'
  span.textContent = `> ${text}\n`
  log.appendChild(span)
}

watch(
  address,
  (value) => {
    account.load(value)
    const row = document.querySelector('.rc .cl-kv b')
    if (row) row.textContent = value ? shortAddress(value) : 'not connected'
    if (value && !scanning) {
      const log = document.querySelector('.rc-log')
      if (log) {
        log.textContent = ''
        logLine('wallet connected · press Recover my funds to scan')
        log.append('  Output stays on this device.')
      }
    }
  },
  { immediate: true },
)

function openConnect() {
  walletError.value = ''
  connectOpen.value = true
}

async function selectWallet(entry) {
  await wallet.connectInjected(entry)
  if (address.value) connectOpen.value = false
}

async function selectBrowser() {
  await wallet.connectBrowser()
  if (address.value) connectOpen.value = false
}

async function recover() {
  if (!connected.value) {
    openConnect()
    return
  }
  if (scanning) return
  scanning = true
  if (button) {
    button.disabled = true
    button.innerHTML = '<span class="rc-spin"></span>Scanning…'
  }
  const pill = document.querySelector('.rc-console .cl-pill')
  if (pill) pill.textContent = 'scanning'
  const log = document.querySelector('.rc-log')
  if (log) log.textContent = ''

  logLine('verifying signature')
  await wait(650)
  logLine('derived 128 burner keys from this wallet')
  await wait(900)
  logLine('checking Robinhood Chain · Base · Arbitrum · BNB Chain')
  await wait(1400)
  logLine('128 burners checked · 0 funded')
  await wait(700)
  logLine(`${account.state.bridges.length} bridge intents verified`)
  await wait(650)
  logLine('scan complete · nothing to recover')

  if (pill) pill.textContent = 'complete'
  if (button) {
    button.disabled = false
    button.textContent = 'Scan again'
  }
  scanning = false
}

onMounted(() => {
  button = document.querySelector('.rc .rc-btn')
  button?.addEventListener('click', recover)
})

onBeforeUnmount(() => {
  button?.removeEventListener('click', recover)
})
</script>
